package com.crypto.laplace.service;
import static org.mockito.Mockito.*;import com.crypto.domain.model.Kline;import com.crypto.laplace.execution.LaplacePaperExecutionService;import com.crypto.laplace.model.*;import com.crypto.laplace.persistence.*;import java.time.Instant;import java.util.*;import org.junit.jupiter.api.Test;
class LaplacePositionManagementServiceTest {
 @Test void skipsEntryAndEarlierCandlesAndStartsWithFirstLaterClose(){var repo=mock(LaplacePaperPositionRepository.class);var klines=mock(FiveMinuteKlineService.class);var execution=mock(LaplacePaperExecutionService.class);Instant entry=Instant.parse("2026-08-06T10:30:00Z");var p=LaplacePaperPositionEntity.builder().id("p").symbol("BTCUSDT").status(LaplacePositionStatus.OPEN).entryCandleCloseTime(entry).lastManagedFiveMinuteCandleCloseTime(entry).build();var next=Kline.builder().closeTime(entry.plusSeconds(300)).build();when(repo.findById("p")).thenReturn(Optional.of(p));when(klines.loadClosedRange("BTCUSDT",entry,entry.plusSeconds(300))).thenReturn(List.of(next));when(execution.evaluateClosedFiveMinuteCandle("p",next)).thenReturn(PositionManagementOutcome.NO_ACTION);new LaplacePositionManagementService(repo,klines,execution).catchUp("p",entry.plusSeconds(300));verify(execution).evaluateClosedFiveMinuteCandle("p",next);}
}
